insert into "kode_item_transaksi_faktur" ("id", "jenis_item_id", "kode", "nama_indonesia", "nama_inggris", "aktif") values ('kode-item-a340300', 'jenis-item-barang', 'A340300', 'Preparat pelumas (termasuk preparat minyak pemotong, preparat pelepas baut atau mur, preparat anti-karat atau anti-korosi dan preparat pelepas cetakan, dengan bahan dasar pelumas) dan preparat dari jenis yang digunakan untuk meminyaki atau menggemuki bahan tekstil, kulit samak, kulit berbulu atau material lainnya, tetapi tidak termasuk preparat yang mengandung minyak petroleum atau minyak yang diperoleh dari mineral mengandung bitumen sebagai unsur dasar, 70 % atau lebih menurut beratnya.', 'Lubricating preparations (including cutting-oil preparations, bolt or nut release preparations, anti-rust or anti-corrosion preparations and mould release preparations, based on lubricants) and preparations of a kind used for the oil or grease treatment of textile materials, leather, furskins or other materials, but excluding preparations containing, as basic constituents, 70 % or more by weight of petroleum oils or of oils obtained from bituminous minerals.', 1) on conflict ("kode_item_transaksi_faktur"."id") do update set "jenis_item_id" = 'jenis-item-barang', "kode" = 'A340300', "nama_indonesia" = 'Preparat pelumas (termasuk preparat minyak pemotong, preparat pelepas baut atau mur, preparat anti-karat atau anti-korosi dan preparat pelepas cetakan, dengan bahan dasar pelumas) dan preparat dari jenis yang digunakan untuk meminyaki atau menggemuki bahan tekstil, kulit samak, kulit berbulu atau material lainnya, tetapi tidak termasuk preparat yang mengandung minyak petroleum atau minyak yang diperoleh dari mineral mengandung bitumen sebagai unsur dasar, 70 % atau lebih menurut beratnya.', "nama_inggris" = 'Lubricating preparations (including cutting-oil preparations, bolt or nut release preparations, anti-rust or anti-corrosion preparations and mould release preparations, based on lubricants) and preparations of a kind used for the oil or grease treatment of textile materials, leather, furskins or other materials, but excluding preparations containing, as basic constituents, 70 % or more by weight of petroleum oils or of oils obtained from bituminous minerals.', "aktif" = 1;--> statement-breakpoint
