insert into "kode_item_transaksi_faktur" ("id", "jenis_item_id", "kode", "nama_indonesia", "nama_inggris", "aktif") values ('kode-item-a851700', 'jenis-item-barang', 'A851700', 'Perangkat telepon, termasuk smartphone dan telepon lainnya untuk jaringan seluler atau untuk jaringan tanpa kabel lainnya； aparatus lainnya untuk mengirimkan atau menerima suara, gambar, atau data lainnya termasuk aparatus untuk komunikasi dalam jaringan kabel atau tanpa kabel (seperti local atau wide area network), selain dari aparat transmisi atau penerima dari pos 84.43, 85.25, 85.27 atau 85.28.', 'Telephone sets, including smartphones and other telephones for cellular networks or for other wireless networks； other apparatus for the transmission or reception of voice, images or other data, including apparatus for communication in a wired or wireless network (such as a local or wide area network), other than transmission or reception apparatus of heading 84.43, 85.25, 85.27 or 85.28.', 1) on conflict ("kode_item_transaksi_faktur"."id") do update set "jenis_item_id" = 'jenis-item-barang', "kode" = 'A851700', "nama_indonesia" = 'Perangkat telepon, termasuk smartphone dan telepon lainnya untuk jaringan seluler atau untuk jaringan tanpa kabel lainnya； aparatus lainnya untuk mengirimkan atau menerima suara, gambar, atau data lainnya termasuk aparatus untuk komunikasi dalam jaringan kabel atau tanpa kabel (seperti local atau wide area network), selain dari aparat transmisi atau penerima dari pos 84.43, 85.25, 85.27 atau 85.28.', "nama_inggris" = 'Telephone sets, including smartphones and other telephones for cellular networks or for other wireless networks； other apparatus for the transmission or reception of voice, images or other data, including apparatus for communication in a wired or wireless network (such as a local or wide area network), other than transmission or reception apparatus of heading 84.43, 85.25, 85.27 or 85.28.', "aktif" = 1;--> statement-breakpoint
